#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.IO;using UnityEngine;using Unity.Profiling;using Unity.Profiling.LowLevel.Unsafe;using DeliveryService.Mok.Navigation;
namespace DeliveryService.Mok.Editor {public static class PerformanceTest {
 public static IEnumerator RunCore(Action<string> log){
 var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);var descriptions=handles.Select(ProfilerRecorderHandle.GetDescription).ToArray();File.WriteAllText("Temp/Mok-profiler-markers.txt",string.Join("\n",descriptions.Select(d=>d.Category.Name+" / "+d.Name+" / "+d.UnitType)));
 var wanted=new[]{"Main Thread","Render Thread","PlayerLoop","EditorLoop","Gfx.WaitForPresentOnGfxThread","Gfx.WaitForRenderThread","WaitForTargetFPS","RenderLoop.DrawSRPBatcher","CullScriptable","RenderLoop","MeshSkinning.Update","Physics.UpdateBodies","Physics.SyncTransforms","BehaviourUpdate","UpdateAllRenderers","PostLateUpdate.UpdateAllRenderers","RenderPipelineManager.DoRenderLoop_Internal","UniversalRenderPipeline.RenderSingleCameraInternal","GC Allocated In Frame","Draw Calls Count","Triangles Count","Physics.Simulate","Physics.Processing","Update.ScriptRunBehaviourUpdate","PreLateUpdate.ScriptRunBehaviourLateUpdate","Camera.Render","RenderPipelineManager.DoRenderLoop_Internal","Animators.Update","NavMeshManager.Update","Mok.TrafficLeader","Mok.Route","Mok.Planner","Mok.HUD","Mok.Merchant"};
 var recorders=new Dictionary<string,ProfilerRecorder>();foreach(var name in wanted.Distinct()){var d=descriptions.FirstOrDefault(x=>x.Name==name);if(d.Name==name)recorders[name]=ProfilerRecorder.StartNew(d.Category,name,1,ProfilerRecorderOptions.Default|ProfilerRecorderOptions.SumAllSamplesInFrame);}
 var p=UnityEngine.Object.FindFirstObjectByType<PlayerCombat>();var clock=UnityEngine.Object.FindFirstObjectByType<DayNightCycle>();clock.currentTime=12;clock.isShopOpen=true;clock.timeMultiplier=0;var camera=p.View;var phone=UnityEngine.Object.FindFirstObjectByType<PhoneController>();var nav=UnityEngine.Object.FindFirstObjectByType<NavigationManager>();var planner=UnityEngine.Object.FindFirstObjectByType<NavigationPlanner>();var bikes=UnityEngine.Object.FindObjectsByType<MotorcycleController>(FindObjectsSortMode.None);foreach(var b in bikes)b.isDriven=false;phone.ClosePhone();p.GetComponent<PlayerMove>().enabled=false;foreach(var look in p.GetComponentsInChildren<CameraMove>())look.enabled=false;p.GetComponent<CharacterController>().enabled=false;
 var rr=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None);log("RENDERERS static="+rr.Count(r=>r.gameObject.isStatic)+" batched="+rr.Count(r=>r.isPartOfStaticBatch)+" propertyBlocks="+rr.Count(r=>r.HasPropertyBlock()));
 foreach(var g in rr.GroupBy(r=>r.transform.root.name).OrderByDescending(g=>g.Count()).Take(18))log("ROOT "+g.Key+" renderers="+g.Count());
 foreach(var g in rr.SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).GroupBy(m=>m.shader.name).OrderByDescending(g=>g.Count()))log("SHADER "+g.Key+" uses="+g.Count()+" materials="+g.Distinct().Count());
 log("CENSUS cars="+UnityEngine.Object.FindObjectsByType<CarMov>(FindObjectsSortMode.None).Length+" citizens="+UnityEngine.Object.FindObjectsByType<NPCControl>(FindObjectsSortMode.None).Length+" renderers="+UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).Length);
 foreach(var c in UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))log($"CAMERA {c.name} enabled={c.enabled} size={c.pixelWidth}x{c.pixelHeight} target={c.targetTexture}");
 var locations=new[]{new Vector3(0,0,50),new Vector3(290,0,-30),new Vector3(-255,0,0)};
 try{for(int region=0;region<3;region++)for(int mode=0;mode<2;mode++){
 p.transform.position=locations[region];camera.transform.position=p.transform.position+Vector3.up*1.65f;camera.transform.rotation=Quaternion.Euler(0,region==2?270:0,0);nav.SetNavigationTarget(p.transform);if(mode==1){phone.TogglePhone();yield return null;planner.Show(NavigationPlanner.Screen.Map);}else phone.ClosePhone();
 double start=UnityEditor.EditorApplication.timeSinceStartup;while(UnityEditor.EditorApplication.timeSinceStartup-start<2)yield return null;
 var samples=recorders.ToDictionary(x=>x.Key,x=>new List<long>());var frames=new List<double>();double previous=UnityEditor.EditorApplication.timeSinceStartup;start=previous;
 while(UnityEditor.EditorApplication.timeSinceStartup-start<4){yield return null;double now=UnityEditor.EditorApplication.timeSinceStartup;frames.Add((now-previous)*1000);previous=now;foreach(var r in recorders)samples[r.Key].Add(r.Value.LastValue);}
 frames.Sort();log($"SCENARIO {region} {(mode==0?"phone-hidden":"map-open")} frames={frames.Count} frameMedian={frames[frames.Count/2]:F2}ms p95={frames[(int)(frames.Count*.95)]:F2}ms");foreach(var pair in samples){pair.Value.Sort();log($"  {pair.Key}: mean={pair.Value.Average():F0} p95={pair.Value[(int)(pair.Value.Count*.95)]}");}
 }}finally{foreach(var r in recorders.Values)r.Dispose();phone.ClosePhone();}
 }
}}
#endif
